patch -p1 <<'PATCH'
--- a/processing/src/test/java/org/apache/druid/query/groupby/GroupByQueryQueryToolChestTest.java
+++ b/processing/src/test/java/org/apache/druid/query/groupby/GroupByQueryQueryToolChestTest.java
@@ -36,6 +36,7 @@
 import org.apache.druid.java.util.common.DateTimes;
 import org.apache.druid.java.util.common.StringUtils;
 import org.apache.druid.java.util.common.granularity.Granularities;
+import org.apache.druid.java.util.common.granularity.Granularity;
 import org.apache.druid.java.util.common.guava.Sequences;
@@ -521,6 +522,48 @@
   }

   @Test
+  public void testResultLevelCacheWithMultiplePostAggregators() throws IOException
+  {
+    final ObjectMapper objectMapper = TestHelper.makeJsonMapper();
+    for (Granularity granularity : ImmutableList.of(Granularities.ALL, Granularities.DAY)) {
+      final GroupByQuery query = GroupByQuery.builder()
+          .setDataSource(QueryRunnerTestHelper.DATA_SOURCE)
+          .setQuerySegmentSpec(QueryRunnerTestHelper.FIRST_TO_THIRD)
+          .setDimensions(
+              DefaultDimensionSpec.of("channel"),
+              DefaultDimensionSpec.of("cityName")
+          )
+          .setAggregatorSpecs(QueryRunnerTestHelper.ROWS_COUNT)
+          .setPostAggregatorSpecs(
+              ImmutableList.of(
+                  new ExpressionPostAggregator("doubleCount", "rows * 2", null, null, TestExprMacroTable.INSTANCE),
+                  new ExpressionPostAggregator("tripleCount", "rows * 3", null, null, TestExprMacroTable.INSTANCE)
+              )
+          )
+          .setGranularity(granularity)
+          .build();
+      final CacheStrategy<ResultRow, Object, GroupByQuery> strategy =
+          new GroupByQueryQueryToolChest(null).getCacheStrategy(query);
+      final ResultRow result = query.getResultRowHasTimestamp()
+                               ? ResultRow.of(123L, "#en.wikipedia", null, 10516, 21032, 31548)
+                               : ResultRow.of("#en.wikipedia", null, 10516, 21032, 31548);
+
+      final Object cachedValue = objectMapper.readValue(
+          objectMapper.writeValueAsBytes(strategy.prepareForCache(true).apply(result)),
+          strategy.getCacheObjectClazz()
+      );
+
+      Assert.assertEquals(result, strategy.pullFromCache(true).apply(cachedValue));
+    }
+  }
+
+  @Test
   public void testMultiColumnCacheStrategy() throws Exception
PATCH
mvn test -o -pl processing -Dtest=GroupByQueryQueryToolChestTest#testResultLevelCacheWithMultiplePostAggregators > /tmp/druid-groupby-cache-regression.log 2>&1; result=$?; tail -65 /tmp/druid-groupby-cache-regression.log; exit "$result"

